import{c as t,S as o,j as a,m as r}from"./chunks/framework.C68YPdek.js";const p=JSON.parse('{"title":"Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/deployment.md","filePath":"developer/architecture/deployment.md"}'),n={name:"developer/architecture/deployment.md"};function s(d,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to “Deployment”">​</a></h1><p>Where each part runs. Checked against the backend&#39;s <code>deployment/</code> folder and the repositories&#39; workflows on 28 November 2026; what is not recorded in a repository is marked as such.</p><h2 id="the-backend-aws-described-in-terraform" tabindex="-1">The backend: AWS, described in Terraform <a class="header-anchor" href="#the-backend-aws-described-in-terraform" aria-label="Permalink to “The backend: AWS, described in Terraform”">​</a></h2><p><code>backend/deployment/terraform</code> describes a deployment in the <code>ap-southeast-1</code> region, with its state in an S3 bucket:</p><ul><li>a <strong>VPC</strong> with public and private subnets, and security groups for the load balancer, the API instances and the database (<code>vpc.tf</code>);</li><li>the <strong>API servers</strong>: an EC2 launch template, an auto-scaling group and an application load balancer (<code>ec2.tf</code>);</li><li>the <strong>database</strong>: an RDS instance, with its password generated and kept in Secrets Manager (<code>rds.tf</code>, <code>sm.tf</code>);</li><li>the <strong>grader</strong>: an AWS Lambda function named <code>&lt;env&gt;-cadet-grader</code>, with handler <code>index.runAll</code>, 512 MB of memory and a configurable timeout (<code>lambda.tf</code>). The file sets the runtime <code>nodejs12.x</code>; whether production uses a newer runtime is not recorded here, and the grader&#39;s current needs should be compared with it;</li><li>two existing <strong>S3 buckets</strong> (assets and configuration) that the file looks up (<code>s3.tf</code>), and an IoT policy for remote execution on devices (<code>iot.tf</code>).</li></ul><p>An API server runs the backend as a <strong>release</strong>: the workflow <code>cd.yml</code> builds it with <code>mix release</code> and publishes it as the GitHub release <code>latest-deploy</code>; <code>deployment/init.sh</code> downloads that tarball and installs the systemd service <code>cadet.service</code> (it also serves as the manual deployment guide for any Linux server with systemd).</p><h2 id="static-sites-github-pages" tabindex="-1">Static sites: GitHub Pages <a class="header-anchor" href="#static-sites-github-pages" aria-label="Permalink to “Static sites: GitHub Pages”">​</a></h2><p>Most of the rest is static files on GitHub Pages, each built by its own repository&#39;s workflow:</p><ul><li>the <strong>directories</strong> (<code>language-directory</code>, <code>plugin-directory</code>, and the plugin directory file of <code>plugins</code>) and the <strong>modules</strong> (<code>modules</code>);</li><li>the <strong>evaluators</strong> (js-slang, py-slang, scm-slang, java-slang, ocaml-slang) and the <strong>plugin bundles</strong> (<code>plugins</code>);</li><li>the playground-only build of the <strong>frontend</strong>, at <a href="https://source-academy.github.io" target="_blank" rel="noreferrer">https://source-academy.github.io</a>;</li><li>the documentation sites: <a href="https://docs.sourceacademy.org" target="_blank" rel="noreferrer">https://docs.sourceacademy.org</a> (this repository publishes into the deployment repository <code>docs.sourceacademy.org</code>, as js-slang and py-slang do) and <a href="https://about.sourceacademy.org" target="_blank" rel="noreferrer">https://about.sourceacademy.org</a> (the <code>about</code> repository).</li></ul><h2 id="the-full-frontend" tabindex="-1">The full frontend <a class="header-anchor" href="#the-full-frontend" aria-label="Permalink to “The full frontend”">​</a></h2><p>The build with login and assessments, for Source Academy @ NUS and for other institutions, is configured by environment variables at build time (the backend&#39;s address, the directory URLs, and so on; see <a href="./frontend">Frontend</a>). Where it is hosted is not recorded in the frontend repository.</p><h2 id="running-your-own" tabindex="-1">Running your own <a class="header-anchor" href="#running-your-own" aria-label="Permalink to “Running your own”">​</a></h2><p>The README of the frontend covers a local playground and a local Source Academy @ NUS; the backend README covers a local backend and the manual deployment on a Linux server. A complete guide to a deployment of one&#39;s own (&quot;Source Academy @ X&quot;) is in the <code>about</code> repository, <a href="https://github.com/source-academy/about/tree/master/deployment" target="_blank" rel="noreferrer"><code>deployment</code></a>.</p>',13)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
